import{_ as o,o as t,c as n,ag as c}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-30（神经科学 / 运动控制 · 行走节律发生器）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-10-30-neuro.md","filePath":"topics/neuroscience/science-daily-2026-10-30-neuro.md"}'),r={name:"topics/neuroscience/science-daily-2026-10-30-neuro.md"};function s(i,e,a,d,l,g){return t(),n("div",null,[...e[0]||(e[0]=[c('<h1 id="科学日报-·-2026-10-30-神经科学-运动控制-·-行走节律发生器" tabindex="-1">科学日报 · 2026-10-30（神经科学 / 运动控制 · 行走节律发生器） <a class="header-anchor" href="#科学日报-·-2026-10-30-神经科学-运动控制-·-行走节律发生器" aria-label="Permalink to &quot;科学日报 · 2026-10-30（神经科学 / 运动控制 · 行走节律发生器）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> — 第49期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-neuro</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-30-神经-·-1-1-果蝇连接组模拟定位「行走节律发生器」——一个三神经元回路" tabindex="-1">科学日报 2026-10-30（神经 · 1/1）：果蝇连接组模拟定位「行走节律发生器」——一个三神经元回路 <a class="header-anchor" href="#科学日报-2026-10-30-神经-·-1-1-果蝇连接组模拟定位「行走节律发生器」——一个三神经元回路" aria-label="Permalink to &quot;科学日报 2026-10-30（神经 · 1/1）：果蝇连接组模拟定位「行走节律发生器」——一个三神经元回路&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ DOI: 10.1038/s41586-026-11195-y ｜ Nature (2026)</p></blockquote><ul><li>问题：动物行走的<strong>腿部节律</strong>由<strong>中枢模式发生器（central pattern generator, CPG）<strong>产生——一类</strong>无需节律性输入</strong>就能输出节律性运动模式的神经网络。问题在于：在<strong>真实的连接组（全脑接线图）<strong>里，这套节律究竟由</strong>哪几个神经元、以怎样的接线</strong>产生？</li><li>方法：以<strong>果蝇连接组（fly connectome）<strong>为基础构建神经网络，做</strong>计算仿真（connectome simulations）</strong>，从接线结构中<strong>搜索能产生行走节律的最小回路</strong>。</li><li>结果：识别出一个<strong>三神经元回路</strong>——其组织方式<strong>足以产生行走所需的腿部运动节律</strong>（即一个可指认的 CPG）。</li><li>洞察（对本库 <code>neuroscience</code> × <code>ai-system-architecture</code>）： <ol><li><strong>「功能可以锚定到具体接线」</strong> —— 不是停留在「某脑区负责行走」的宏观定位，而是<strong>在结构上指认出能复现该节律的回路</strong>。判据：<strong>当一个行为节律要归因到神经机制时，目标是找到「够用的最小回路」（必要且充分），而不是「相关脑区」。</strong></li><li><strong>「连接组 = 可仿真的先验结构」</strong> —— 从<strong>接线图</strong>出发做仿真找回路，本质是<strong>把结构当搜索空间的约束</strong>，而非从零训练网络去拟合行为。这与本库 <code>ai-system-architecture</code> 的「<strong>把归纳偏置做进结构</strong>」（10-29 Wilson 环注意力、ASF 规范不变性）跨域同构：<strong>先有结构约束，再谈功能。</strong></li><li><strong>一句话定位</strong>：与 10-26 头固定鼠「HD 环形吸引子」、10-24 乌鸦「端脑方向选择神经元爬坡」同属「<strong>把行为归因到可指认的神经动力学</strong>」这条 <code>neuroscience</code> 主线；本条把抓手从「电生理记录」换成「<strong>连接组仿真</strong>」。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ <code>topics/ai-system-architecture/index.md</code> ｜ 第49期 科学板块</p></blockquote><p>关键词：科学日报第49期、果蝇连接组 fly connectome、计算仿真 connectome simulation、中枢模式发生器 CPG、行走节律、腿部运动节律、三神经元回路、无需节律性输入、节律性运动模式、最小充分回路、功能锚定接线、结构约束搜索空间、连接组作为先验、运动控制</p><p>关联：<code>topics/neuroscience/index.md</code>、<code>topics/neuroscience/science-daily-2026-10-29-neuro.md</code>（围产期清算异常神经元）、<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-brain/index.md</code></p>',10)])])}const m=o(r,[["render",s]]);export{p as __pageData,m as default};
